<template>
  <div class="monitor-shell"><header class="topbar"><div class="brand"><span>⚡</span><b>Seckill<span>Core</span></b><em>实时监控</em></div><div class="top-actions"><span :class="overallClass"><i></i>{{ overallStatus }}</span><small>最近更新：{{ lastUpdated }}</small><button type="button" title="刷新" :disabled="loading" @click="refresh">↻</button></div></header><main class="content"><section class="overview"><div><p>业务健康监控</p><h1>实时运行状态</h1><span>探测网关业务接口，观察服务可用性与响应延迟</span></div><div class="monitor-controls"><span class="interval"><i></i> 每 30 秒自动刷新</span><button type="button" @click="autoRefresh = !autoRefresh">{{ autoRefresh ? '暂停刷新' : '开启刷新' }}</button></div></section><section class="metric-grid"><article v-for="metric in metrics" :key="metric.label"><div class="metric-top"><span>{{ metric.label }}</span><b :class="metric.tone">{{ metric.icon }}</b></div><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small><div v-if="metric.chart.length" class="sparkline"><i v-for="(height, index) in metric.chart" :key="index" :style="{ height: `${height}%` }"></i></div></article></section><section class="dashboard-grid"><div class="panel chart-panel"><div class="panel-heading"><div><h2>接口响应趋势</h2><p>最近 {{ latencyHistory.length || 1 }} 次探测平均耗时</p></div><strong class="chart-value">{{ averageLatency }} <small>ms</small></strong></div><div ref="chartRef" class="chart"></div><div v-if="!latencyHistory.length" class="chart-empty"><span>◌</span><b>等待第一次探测</b><small>刷新后展示响应时间趋势</small></div></div><div class="panel health-panel"><div class="panel-heading"><div><h2>服务健康度</h2><p>当前业务接口探测结果</p></div><span class="health-badge" :class="overallClass">{{ healthyCount }}/{{ services.length }} 正常</span></div><div v-for="service in services" :key="service.key" class="service-row"><span class="service-dot" :class="service.status"></span><div><b>{{ service.name }}</b><small>{{ service.endpoint }}</small></div><span class="latency">{{ service.latency ? `${service.latency} ms` : '--' }}</span><strong :class="service.status">{{ service.status === 'healthy' ? '正常' : service.status === 'checking' ? '探测中' : '异常' }}</strong></div></div></section><section class="panel event-panel"><div class="panel-heading"><div><h2>探测记录</h2><p>最近一次接口检查结果</p></div><button type="button" @click="refresh">立即检查</button></div><div v-if="events.length" class="event-list"><div v-for="event in events" :key="event.id" class="event-row"><i :class="event.type"></i><span>{{ event.message }}</span><time>{{ event.time }}</time></div></div><div v-else class="event-empty"><span>✓</span><div><b>暂无异常事件</b><small>系统会在探测到接口异常时记录事件</small></div></div></section></main></div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { probe } from './api'

const chartRef = ref(null); const loading = ref(false); const autoRefresh = ref(true); const lastUpdated = ref('--'); const latencyHistory = ref([]); const events = ref([]); let chart; let timer; let eventId = 0
const services = ref([{ key: 'products', name: 'Product Service', endpoint: 'GET /api/v1/product/list', status: 'checking', latency: 0 }, { key: 'activities', name: 'Activity Service', endpoint: 'GET /api/v1/activity/list', status: 'checking', latency: 0 }, { key: 'users', name: 'User Service', endpoint: 'GET /api/v1/users', status: 'checking', latency: 0 }])
const snapshot = ref({ products: 0, activities: 0, activeActivities: 0, users: 0 }); const healthyCount = computed(() => services.value.filter((item) => item.status === 'healthy').length); const overallClass = computed(() => healthyCount.value === services.value.length ? 'healthy' : healthyCount.value ? 'degraded' : 'down'); const overallStatus = computed(() => overallClass.value === 'healthy' ? '系统运行正常' : overallClass.value === 'degraded' ? '部分服务异常' : '服务不可用'); const averageLatency = computed(() => latencyHistory.value.length ? Math.round(latencyHistory.value.reduce((sum, value) => sum + value, 0) / latencyHistory.value.length) : '--')
const metrics = computed(() => [{ label: '商品总数', value: snapshot.value.products, note: 'Product Service', icon: '◇', tone: 'blue', chart: [22, 27, 31, 29, 35, 32] }, { label: '进行中活动', value: snapshot.value.activeActivities, note: 'Activity Service', icon: '◷', tone: 'green', chart: [42, 36, 39, 44, 40, 46] }, { label: '平台用户数', value: snapshot.value.users, note: 'User Service', icon: '◎', tone: 'purple', chart: [29, 31, 30, 33, 35, 36] }, { label: '平均响应时间', value: averageLatency.value === '--' ? '--' : `${averageLatency.value} ms`, note: '最近一次探测', icon: '◷', tone: 'orange', chart: latencyHistory.value.length ? [35, 40, 32, 43, 38, 45] : [] }])
function unwrap(result) { return result?.data?.records || [] }
function now() { return new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(new Date()) }
function addEvent(type, message) { events.value.unshift({ id: ++eventId, type, message, time: now() }); events.value = events.value.slice(0, 5) }
async function refresh() { if (loading.value) return; loading.value = true; services.value.forEach((service) => { service.status = 'checking'; service.latency = 0 }); const checks = [{ key: 'products', path: '/api/v1/product/list?page=1&size=1' }, { key: 'activities', path: '/api/v1/activity/list?page=1&size=1' }, { key: 'users', path: '/api/v1/users?page=1&size=1' }]; const started = performance.now(); const results = await Promise.allSettled(checks.map((item) => probe(item.path))); results.forEach((outcome, index) => { const service = services.value.find((item) => item.key === checks[index].key); if (outcome.status === 'fulfilled') { service.status = 'healthy'; service.latency = outcome.value.latency; if (service.key === 'products') snapshot.value.products = outcome.value.result?.data?.total || unwrap(outcome.value.result).length; if (service.key === 'activities') { const items = unwrap(outcome.value.result); snapshot.value.activities = outcome.value.result?.data?.total || items.length; snapshot.value.activeActivities = items.filter((item) => item.status === 1).length } if (service.key === 'users') snapshot.value.users = outcome.value.result?.data?.total || unwrap(outcome.value.result).length } else { service.status = 'down'; addEvent('error', `${service.name} 探测失败：${outcome.reason?.message || '连接异常'}`) } }); const elapsed = Math.round(performance.now() - started); latencyHistory.value = [...latencyHistory.value, elapsed].slice(-12); lastUpdated.value = now(); if (results.every((item) => item.status === 'fulfilled')) addEvent('success', `全部业务接口探测完成，耗时 ${elapsed} ms`); loading.value = false; await nextTick(); updateChart() }
function updateChart() { if (!chartRef.value) return; if (!chart) chart = echarts.init(chartRef.value); chart.setOption({ animation: false, grid: { left: 12, right: 10, top: 12, bottom: 24 }, xAxis: { type: 'category', boundaryGap: false, data: latencyHistory.value.map((_, index) => `${index + 1}`), axisLine: { lineStyle: { color: '#e5ebf2' } }, axisLabel: { color: '#a0adbc', fontSize: 10 } }, yAxis: { type: 'value', min: 0, splitNumber: 3, axisLabel: { color: '#a0adbc', fontSize: 10 }, splitLine: { lineStyle: { color: '#eef2f6' } } }, series: [{ type: 'line', smooth: true, data: latencyHistory.value, symbol: 'circle', symbolSize: 6, lineStyle: { width: 2, color: '#4d8beb' }, itemStyle: { color: '#4d8beb' }, areaStyle: { color: 'rgba(77,139,235,.12)' } }] }) }
watch(autoRefresh, (enabled) => { clearInterval(timer); if (enabled) timer = setInterval(refresh, 30000) }); onMounted(() => { refresh(); timer = setInterval(refresh, 30000); window.addEventListener('resize', () => chart?.resize()) }); onBeforeUnmount(() => { clearInterval(timer); chart?.dispose() })
</script>

<style scoped>
