:column;gap:9px;pointer-events:none}.chart-empty span{display:grid;width:37px;height:37px;place-items:center;border:1px dashed #b8cce9;border-radius:50%;color:#75a1dc;font-size:20px}.chart-empty b{color:#687a91;font-size:12px}.chart-empty small{color:#adb8c5;font-size:10px}.health-badge{padding:5px 8px;border-radius:5px;color:#39a976;font-size:10px;background:#eef9f4}.health-badge.degraded{color:#c88c42;background:#fff6e8}.health-badge.down{color:#d45d63;background:#fff1f1}.service-row{display:flex;margin-top:21px;align-items:center;gap:10px}.service-dot{width:8px;height:8px;border-radius:50%;background:#aebac8}.service-dot.healthy{background:#42bd82}.service-dot.checking{background:#6fa6ec;animation:pulse 1s infinite}.service-dot.down{background:#e36d75}.service-row div{display:flex;flex:1;flex-direction:column;gap:4px}.service-row b{color:#53647b;font-size:12px}.service-row small{color:#a1adbd;font-size:10px}.service-row strong{color:#a1adbd;font-size:10px;font-weight:500}.service-row strong.healthy{color:#3cad79}.service-row strong.down{color:#d45d63}.latency{color:#8494a8;font-size:10px}.event-panel{margin-top:16px}.event-panel .panel-heading button{padding:0;border:0;color:#3479e9;font:inherit;font-size:11px;background:none;cursor:pointer}.event-list{margin-top:19px}.event-row{display:flex;padding:11px 0;align-items:center;gap:10px;border-bottom:1px solid #f0f3f6;color:#677991;font-size:11px}.event-row i{width:7px;height:7px;border-radius:50%;background:#42bd82}.event-row i.error{background:#e36d75}.event-row time{margin-left:auto;color:#a5b1c0;font-size:10px}.event-empty{display:flex;margin-top:24px;padding:20px;align-items:center;gap:13px;border:1px dashed #dce5ef;border-radius:9px;background:#fbfcfe}.event-empty>span{display:grid;width:30px;height:30px;place-items:center;border-radius:50%;color:#42b783;background:#eaf8f1}.event-empty div{display:flex;flex-direction:column;gap:5px}.event-empty b{color:#5f7188;font-size:12px}.event-empty small{color:#a4b0bd;font-size:10px}@keyframes pulse{50%{opacity:.35}}@media(max-width:850px){.metric-grid{grid-template-columns:repeat(2,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:560px){.topbar{padding:0 16px}.top-actions small,.top-actions>span{display:none}.content{padding:28px 16px}.overview{display:block}.monitor-controls{margin-top:20px;justify-content:space-between}.metric-grid{grid-template-columns:1fr}.metric-grid article{min-height:140px}}
</style>
